{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 청년 기본 조례상 취업 준비 중 버스·지하철 등 교통비 지원 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 청년 기본 조례 제15조 제3항에 따르면, 시장은 청년의 생활안정을 위하여 예산의 범위에서 대중교통수단을 이용할 경우 그 비용을 지원할 수 있다. 여기서 ‘청년’은 같은 조례 제3조 제1호에 따라 19세 이상 39세 이하의 사람을 말한다. 따라서 취업 준비 중인 청년이 버스·지하철 등 대중교통을 이용하는 경우, 예산 범위 내에서 교통비 지원을 받을 수 있는 근거가 있다.",
          "b_ids": "청년:제15조제3항, 청년:제3조제1호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
